//! The settings schema and the user's values.
//!
//! The schema (shell/settings.schema.json, generated by tools/schema.py) is compiled in: it is the
//! one list of every setting, its type, its limits and its default. The user's values live in
//! ~/.config/samurai/settings.json and hold only what differs from the defaults. Every write is
//! checked against the schema; a value of the wrong type or out of range is refused, never clamped
//! silently.
use serde_json::{json, Map, Value};
use std::path::PathBuf;

pub const SCHEMA: &str = include_str!("../../settings/schema.json");

pub fn home() -> PathBuf {
    PathBuf::from(std::env::var_os("HOME").unwrap_or_else(|| "/".into()))
}
pub fn config_dir() -> PathBuf {
    std::env::var_os("SAMURAI_CONFIG").map(PathBuf::from).unwrap_or_else(|| {
        std::env::var_os("XDG_CONFIG_HOME").filter(|v| !v.is_empty()).map(PathBuf::from).unwrap_or_else(|| home().join(".config")).join("samurai")
    })
}
pub fn state_dir() -> PathBuf {
    std::env::var_os("SAMURAI_STATE").map(PathBuf::from).unwrap_or_else(|| {
        std::env::var_os("XDG_STATE_HOME").filter(|v| !v.is_empty()).map(PathBuf::from).unwrap_or_else(|| home().join(".local/state")).join("samurai")
    })
}
pub fn settings_file() -> PathBuf {
    config_dir().join("settings.json")
}

/// write through a temporary file in the same directory, then rename: a crash never leaves half a file
pub fn atomic_write(path: &std::path::Path, text: &str) -> std::io::Result<()> {
    if let Some(d) = path.parent() {
        std::fs::create_dir_all(d)?;
    }
    let tmp = path.with_extension(format!("tmp{}", std::process::id()));
    std::fs::write(&tmp, text)?;
    std::fs::rename(&tmp, path)
}

pub fn schema() -> Value {
    serde_json::from_str(SCHEMA).expect("the built-in schema is valid JSON")
}

/// every setting of the schema: (item, page id)
pub fn items() -> Vec<(Value, String)> {
    let mut v = vec![];
    for p in schema()["pages"].as_array().cloned().unwrap_or_default() {
        let pid = p["id"].as_str().unwrap_or("").to_string();
        for s in p["sections"].as_array().cloned().unwrap_or_default() {
            for i in s["items"].as_array().cloned().unwrap_or_default() {
                if !i["key"].as_str().unwrap_or("").is_empty() {
                    v.push((i, pid.clone()));
                }
            }
        }
    }
    v
}

pub fn item(key: &str) -> Option<Value> {
    items().into_iter().map(|x| x.0).find(|i| i["key"] == key)
}

/// the user's own values (only what they changed)
pub fn user() -> Map<String, Value> {
    std::fs::read_to_string(settings_file()).ok().and_then(|t| serde_json::from_str::<Value>(&t).ok()).and_then(|v| v.as_object().cloned()).unwrap_or_default()
}

/// every setting with its current value: defaults, overlaid by the user's valid values
pub fn all() -> Map<String, Value> {
    let u = user();
    let mut m = Map::new();
    for (i, _) in items() {
        let k = i["key"].as_str().unwrap().to_string();
        let v = match u.get(&k) {
            Some(v) if check(&i, v).is_ok() => v.clone(),
            _ => i["default"].clone(),
        };
        m.insert(k, v);
    }
    m
}

pub fn get(key: &str) -> Value {
    all().get(key).cloned().unwrap_or(Value::Null)
}
pub fn get_str(key: &str) -> String {
    match get(key) {
        Value::String(s) => s,
        Value::Null => String::new(),
        v => v.to_string(),
    }
}
pub fn get_bool(key: &str) -> bool {
    get(key).as_bool().unwrap_or(false)
}
pub fn get_f64(key: &str) -> f64 {
    get(key).as_f64().unwrap_or(0.0)
}
pub fn get_list(key: &str) -> Vec<Value> {
    get(key).as_array().cloned().unwrap_or_default()
}

/// HH:MM, 00:00 … 23:59 (the only pattern the schema uses)
fn is_time(s: &str) -> bool {
    let Some((h, m)) = s.split_once(':') else { return false };
    h.len() <= 2 && m.len() == 2 && h.parse::<u32>().is_ok_and(|h| h < 24) && m.parse::<u32>().is_ok_and(|m| m < 60)
}

/// Is `v` an acceptable value for schema item `i`?
pub fn check(i: &Value, v: &Value) -> Result<(), String> {
    let key = i["key"].as_str().unwrap_or("");
    let bad = |m: String| Err(format!("{key}: {m}"));
    match i["type"].as_str().unwrap_or("") {
        "toggle" => v.is_boolean().then_some(()).ok_or(format!("{key}: needs true or false")),
        "int" | "float" => {
            let Some(n) = v.as_f64() else { return bad("needs a number".into()) };
            if i["type"] == "int" && n.fract() != 0.0 {
                return bad("needs a whole number".into());
            }
            let (lo, hi) = (i["min"].as_f64().unwrap_or(f64::MIN), i["max"].as_f64().unwrap_or(f64::MAX));
            if !n.is_finite() || n < lo || n > hi {
                return bad(format!("{n} is outside {lo} … {hi}"));
            }
            Ok(())
        }
        "enum" => {
            let vals: Vec<Value> = i["options"].as_array().map(|o| o.iter().map(|x| x.get("value").cloned().unwrap_or(x.clone())).collect()).unwrap_or_default();
            let names: Vec<String> = vals.iter().map(|v| v.as_str().unwrap_or("").to_string()).collect();
            vals.contains(v).then_some(()).ok_or(format!("{key}: {v} is not one of {}", names.join(", ")))
        }
        "text" => match v.as_str() {
            Some(s) if i.get("pattern").is_some() && !is_time(s) => bad(format!("\"{s}\" is not a time like 07:30")),
            Some(s) if s.len() <= 512 && !s.chars().any(|c| c.is_control()) => Ok(()),
            Some(_) => bad("too long, or holds control characters".into()),
            None => bad("needs text".into()),
        },
        "color" => match v.as_str() {
            Some(s) if s.len() == 7 && s.starts_with('#') && s[1..].chars().all(|c| c.is_ascii_hexdigit()) => Ok(()),
            _ => bad("needs a colour like #C8102E".into()),
        },
        "list" => {
            let Some(rows) = v.as_array() else { return bad("needs a list".into()) };
            if rows.len() > 500 {
                return bad("too many rows".into());
            }
            let cols: Vec<&str> = i["columns"].as_array().map(|c| c.iter().filter_map(|x| x.as_str()).collect()).unwrap_or_default();
            for r in rows {
                let Some(o) = r.as_object() else { return bad("each row needs to be an object".into()) };
                for (k, val) in o {
                    if !cols.contains(&k.as_str()) {
                        return bad(format!("unknown column {k}"));
                    }
                    match val.as_str() {
                        Some(s) if s.len() <= 1024 && !s.chars().any(|c| c.is_control()) => {}
                        _ => return bad(format!("column {k} needs plain text")),
                    }
                }
            }
            Ok(())
        }
        t => bad(format!("type {t} holds no value")),
    }
}

/// Set one value. A value equal to the default is removed from the file (the file holds only changes).
pub fn set(key: &str, v: Value) -> Result<(), String> {
    let i = item(key).ok_or(format!("{key}: no such setting"))?;
    if i["secret"] == true && v.as_str().is_some_and(|s| !s.is_empty()) {
        return Err(format!("{key}: secrets are kept in the keyring, never in settings.json"));
    }
    check(&i, &v)?;
    let mut u = user();
    if v == i["default"] {
        u.remove(key);
    } else {
        u.insert(key.to_string(), v);
    }
    save(&u)
}

pub fn save(u: &Map<String, Value>) -> Result<(), String> {
    let text = serde_json::to_string_pretty(&Value::Object(u.clone())).map_err(|e| e.to_string())? + "\n";
    atomic_write(&settings_file(), &text).map_err(|e| format!("{}: {e}", settings_file().display()))?;
    // the last good copy, for `samurai doctor` to restore if the file is ever damaged
    let _ = atomic_write(&good_copy(), &text);
    Ok(())
}

pub fn good_copy() -> PathBuf {
    config_dir().join("settings.json.good")
}

/// Back to defaults: one key, one page (by id), or everything ("all").
pub fn reset(what: &str) -> Result<usize, String> {
    let mut u = user();
    let before = u.len();
    if what == "all" {
        u.clear();
    } else if item(what).is_some() {
        u.remove(what);
    } else {
        let keys: Vec<String> = items().into_iter().filter(|(_, p)| p == what).map(|(i, _)| i["key"].as_str().unwrap().to_string()).collect();
        if keys.is_empty() {
            return Err(format!("{what}: neither a setting nor a page"));
        }
        u.retain(|k, _| !keys.contains(k));
    }
    save(&u)?;
    Ok(before - u.len())
}

/// state.json: what the shell watches (incognito, staged update, base in use)
pub fn state() -> Map<String, Value> {
    std::fs::read_to_string(state_dir().join("state.json")).ok().and_then(|t| serde_json::from_str::<Value>(&t).ok()).and_then(|v| v.as_object().cloned()).unwrap_or_default()
}
pub fn set_state(key: &str, v: Value) -> Result<(), String> {
    let mut s = state();
    s.insert(key.to_string(), v);
    atomic_write(&state_dir().join("state.json"), &(json!(s).to_string() + "\n")).map_err(|e| e.to_string())
}

#[cfg(test)]
mod t {
    use super::*;

    #[test]
    fn the_schema_is_sound() {
        let its = items();
        assert!(its.len() > 60, "every page's settings are there: {}", its.len());
        for (i, _) in &its {
            assert!(check(i, &i["default"]).is_ok(), "default of {} passes its own check", i["key"]);
            assert!(!i["label"].as_str().unwrap_or("").is_empty(), "{} has a label", i["key"]);
        }
    }

    #[test]
    fn wrong_values_are_refused() {
        let gap = item("windows.gap").unwrap();
        assert!(check(&gap, &json!(8)).is_ok());
        assert!(check(&gap, &json!(8.5)).is_err());
        assert!(check(&gap, &json!(999)).is_err());
        assert!(check(&gap, &json!("8")).is_err());
        assert!(check(&item("look.ground").unwrap(), &json!("purple")).is_err());
        assert!(check(&item("look.ground").unwrap(), &json!("sun")).is_ok());
        assert!(check(&item("look.sun_from").unwrap(), &json!("7:30")).is_ok());
        assert!(check(&item("look.sun_from").unwrap(), &json!("25:00")).is_err());
        let keys = item("keys.custom").unwrap();
        assert!(check(&keys, &json!([{ "keys": "Super+T", "action": "spawn alacritty" }])).is_ok());
        assert!(check(&keys, &json!([{ "nope": "x" }])).is_err());
        assert!(check(&keys, &json!([{ "keys": "a\nb" }])).is_err());
    }
}
